CREATE TABLE IF NOT EXISTS public.story_views ( id UUID DEFAULT uuid_generate_v4() PRIMARY KEY, story_id UUID REFERENCES public.stories(id) ON DELETE CASCADE NOT NULL, viewer_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::text, NOW()) NOT NULL, UNIQUE(story_id, viewer_id) ); ALTER TABLE public.story_views ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Enable read for everyone" ON public.story_views; CREATE POLICY "Enable read for everyone" ON public.story_views FOR SELECT USING (true); DROP POLICY IF EXISTS "Enable insert for authenticated users" ON public.story_views; CREATE POLICY "Enable insert for authenticated users" ON public.story_views FOR INSERT WITH CHECK (true); ALTER PUBLICATION supabase_realtime ADD TABLE public.story_views;
CREATE TABLE IF NOT EXISTS public.story_likes ( id UUID DEFAULT uuid_generate_v4() PRIMARY KEY, story_id UUID REFERENCES public.stories(id) ON DELETE CASCADE NOT NULL, user_id UUID REFERENCES public.profiles(id) ON DELETE CASCADE NOT NULL, created_at TIMESTAMP WITH TIME ZONE DEFAULT TIMEZONE('utc'::text, NOW()) NOT NULL, UNIQUE(story_id, user_id) ); ALTER TABLE public.story_likes ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS "Enable read for everyone" ON public.story_likes; CREATE POLICY "Enable read for everyone" ON public.story_likes FOR SELECT USING (true); DROP POLICY IF EXISTS "Enable insert for authenticated users" ON public.story_likes; CREATE POLICY "Enable insert for authenticated users" ON public.story_likes FOR INSERT WITH CHECK (true); DROP POLICY IF EXISTS "Enable delete for user" ON public.story_likes; CREATE POLICY "Enable delete for user" ON public.story_likes FOR DELETE USING (true); ALTER PUBLICATION supabase_realtime ADD TABLE public.story_likes;
